INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/02-prerequisites', 'complete-guide-zitadel', '02-prerequisites', 'prerequisites', 'Prerequisites', 'Zitadel Prerequisites: Just Postgres | Simplest Authentication Setup Guide', NULL, NULL, NULL, NULL, 'Getting Started', 2, '{"id":"a5uhh9oosvj8ytch0tf84uja","thumbnailUrl":"https://content.rawkode.academy/videos/a5uhh9oosvj8ytch0tf84uja/thumbnail.jpg"}', NULL, NULL, 1751414400, 0, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"prerequisites"},"content":[{"type":"text","text":"Prerequisites"}]},{"type":"paragraph","content":[{"type":"text","text":"The only prerequisite for running Zitadel is Postgres - that''s it. This tutorial shows you exactly how to set up Postgres with Docker Compose for Zitadel development, including production deployment advice for Kubernetes environments. Learn why managed Postgres services beat DIY every time, discover the Cloud Native PG operator for Kubernetes, and get a working 10-line Docker Compose file that just works. No fluff, no complex dependencies - just the bare minimum you need to start building with Zitadel."}]}]}', 1790105224000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/03-install-docker-compose', 'complete-guide-zitadel', '03-install-docker-compose', 'install-docker-compose', 'How to Install Zitadel with Docker Compose (Step-by-Step)', 'Run Zitadel locally with Docker Compose and Postgres: health checks, master key, TLS for dev, and the console on localhost:8080.', NULL, NULL, NULL, NULL, 'Getting Started', 3, '{"id":"fh6co0t0jsacv1wou1q7iyj7","thumbnailUrl":"https://content.rawkode.academy/videos/fh6co0t0jsacv1wou1q7iyj7/thumbnail.jpg"}', NULL, NULL, 1752278400, 0, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"local-development-setup"},"content":[{"type":"text","text":"Local development setup"}]},{"type":"paragraph","content":[{"type":"text","text":"Learn how to build a local development setup for Zitadel with Docker Compose without breaking your quickstart with race conditions. This hands-on tutorial covers extending your Docker Compose file to run Zitadel alongside Postgres, handling service dependencies, configuring health checks, and avoiding common pitfalls. Includes master key setup, TLS configuration for development, and getting the Zitadel console running on localhost:8080. Follow along with the actual Zitadel documentation examples and learn why order matters in your compose files. Perfect for developers who want a working Zitadel setup fast without the headaches."}]}]}', 1790105224000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/04-install-kubernetes', 'complete-guide-zitadel', '04-install-kubernetes', 'install-kubernetes', 'Installing Zitadel on Kubernetes with Helm', 'This comprehensive hands-on tutorial demonstrates how to deploy Zitadel, the modern identity and access management platform, to a Kubernetes cluster using the official Helm charts. Starting with essential prerequisites including a running Kubernetes cluster (kind, minikube, or cloud-based) and the ability to execute kubectl and Helm commands, you''ll learn the complete deployment process from start to finish.', NULL, NULL, NULL, NULL, 'Getting Started', 4, '{"id":"b7bcg1fl06z4q9529ryalcj2","thumbnailUrl":"https://content.rawkode.academy/videos/b7bcg1fl06z4q9529ryalcj2/thumbnail.jpg"}', NULL, NULL, 1752105600, 0, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"what-youll-learn"},"content":[{"type":"text","text":"What You''ll Learn"}]},{"type":"heading","attrs":{"level":3,"id":"prerequisites-and-setup"},"content":[{"type":"text","text":"Prerequisites and Setup"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting up a Kubernetes cluster (kind, minikube, or cloud-based)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Installing and configuring kubectl and Helm"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Exploring the official "},{"type":"text","text":"zitadel/zitadel-charts","marks":[{"type":"code"}]},{"type":"text","text":" repository"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Understanding deployment examples and configuration options"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"database-configuration"},"content":[{"type":"text","text":"Database Configuration"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PostgreSQL Best Practices","marks":[{"type":"bold"}]},{"type":"text","text":": Learn why providing your own PostgreSQL instance is recommended over Helm dependencies"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CloudNativePG Setup","marks":[{"type":"bold"}]},{"type":"text","text":": Practical demonstration of setting up a simple but effective PostgreSQL cluster"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Database Credentials","marks":[{"type":"bold"}]},{"type":"text","text":": Configuring admin and user database credentials securely"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Secret Management","marks":[{"type":"bold"}]},{"type":"text","text":": Using environment variables for sensitive configuration data"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"core-installation-process"},"content":[{"type":"text","text":"Core Installation Process"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding the Zitadel Helm repository"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configuring the deployment values file"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting up critical security configurations including master key management"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Executing the Helm installation with real terminal commands"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Troubleshooting common deployment issues"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"accessing-and-validating-the-deployment"},"content":[{"type":"text","text":"Accessing and Validating the Deployment"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configuring external domain settings for local development"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting up port forwarding to access the Zitadel console"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initial admin login and password configuration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Validating the deployment with kubectl commands"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"advanced-production-configurations"},"content":[{"type":"text","text":"Advanced Production Configurations"}]},{"type":"heading","attrs":{"level":3,"id":"security-and-secrets-management"},"content":[{"type":"text","text":"Security and Secrets Management"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Referenced Secrets","marks":[{"type":"bold"}]},{"type":"text","text":": Enhanced security through Kubernetes secret integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Master Key Configuration","marks":[{"type":"bold"}]},{"type":"text","text":": Secure generation and storage of encryption keys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Non-root Execution","marks":[{"type":"bold"}]},{"type":"text","text":": Security contexts for safer container operations"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"high-availability-and-scaling"},"content":[{"type":"text","text":"High Availability and Scaling"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-replica Setup","marks":[{"type":"bold"}]},{"type":"text","text":": Configuring high availability with multiple Zitadel instances"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pod Disruption Budgets","marks":[{"type":"bold"}]},{"type":"text","text":": Ensuring zero-downtime during updates and maintenance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource Management","marks":[{"type":"bold"}]},{"type":"text","text":": CPU, memory, and storage configuration for production workloads"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"production-infrastructure"},"content":[{"type":"text","text":"Production Infrastructure"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ingress Configuration","marks":[{"type":"bold"}]},{"type":"text","text":": Setting up external access through ingress controllers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"TLS and DNS","marks":[{"type":"bold"}]},{"type":"text","text":": Proper domain and certificate management"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitoring Integration","marks":[{"type":"bold"}]},{"type":"text","text":": Metrics collection for Prometheus and service monitors"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Additional Manifests","marks":[{"type":"bold"}]},{"type":"text","text":": Deploying complementary services like secrets, service mesh config, or OpenTelemetry collectors"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"day-two-operations"},"content":[{"type":"text","text":"Day-Two Operations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitoring and observability setup"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Update and upgrade strategies"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Backup and disaster recovery considerations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Performance tuning and optimization"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"outcome"},"content":[{"type":"text","text":"Outcome"}]},{"type":"paragraph","content":[{"type":"text","text":"By the end of this tutorial, you''ll have a "},{"type":"text","text":"fully functional, production-ready Zitadel deployment","marks":[{"type":"bold"}]},{"type":"text","text":" running securely on Kubernetes, complete with:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Secure PostgreSQL integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Proper secret management"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ High availability configuration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Monitoring and metrics collection"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Production-grade security settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ External access configuration"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This foundation prepares you for the next phase: setting up your first Zitadel project and configuring authentication flows."}]}]}', 1790105224000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/05-zitadel-cloud', 'complete-guide-zitadel', '05-zitadel-cloud', 'zitadel-cloud', 'Zitadel Cloud', 'Learn how to get started with Zitadel Cloud, the managed service for Zitadel. In less than five minutes, you can have a fully functional Zitadel instance without managing any infrastructure. This is perfect for prototyping, side projects, or evaluating Zitadel quickly.', NULL, NULL, NULL, NULL, 'Getting Started', 5, '{"id":"wcktaod7wsyzhg7rm0z3p1s3","thumbnailUrl":"https://content.rawkode.academy/videos/wcktaod7wsyzhg7rm0z3p1s3/thumbnail.jpg"}', NULL, NULL, 1752624000, 0, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"So far, we''ve covered setting up Zitadel with Docker Compose and Kubernetes, but what if you don''t want to manage any infrastructure at all? What if you just want to get started with Zitadel in the next five minutes without thinking about Postgres, or health checks, Helm charts? Well, you''re in luck. That is where Zitadel Cloud comes in."}]},{"type":"paragraph","content":[{"type":"text","text":"Using a managed service means you can focus entirely on building your application. Instead of managing infrastructure, you get all the power of Zitadel without any of the operational overhead."}]},{"type":"paragraph","content":[{"type":"text","text":"So when you''re prototyping, building a side project or just want to evaluate Zitadel quickly. Zitadel Cloud is the fastest way to get running, so let''s head over to zitadel.com and get started."}]},{"type":"heading","attrs":{"level":2,"id":"generous-free-tier"},"content":[{"type":"text","text":"Generous Free Tier"}]},{"type":"paragraph","content":[{"type":"text","text":"There is a generous, free tier. There are no restrictions on any of the features. They are all available including 2FA, Passkeys, machine to machine, et cetera. You can have unlimited users with a caveat that only 100 daily active users are allowed on the free tier, which is gonna get you from prototype to production without spending a dime."}]},{"type":"paragraph","content":[{"type":"text","text":"This even supports your B2B use cases where you can have unlimited organizations within your setup. You are restricted to three identity providers, but realistically, you''re only gonna want one or two. GitHub and Google, right? And there is no support, but that''s why I''m here."}]},{"type":"heading","attrs":{"level":2,"id":"when-to-use-zitadel-cloud-vs-self-hosting"},"content":[{"type":"text","text":"When to use Zitadel Cloud vs Self-Hosting"}]},{"type":"paragraph","content":[{"type":"text","text":"The main advantage here is that Zitadel handles all the infrastructure management updates, scaling and monitoring. For you. You get enterprise grade reliability without needing to build that expertise in house. So when should you use Zitadel Cloud versus self hosting?"}]},{"type":"paragraph","content":[{"type":"text","text":"Well use cloud when you want to:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Focus on building your application and not managing infrastructure"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prototyping or building a proof of concept"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer predictable monthly pricing over infrastructure costs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Want automatic updates with that enterprise grade reliability"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Of course, you can also self-host, as we''ve covered in previous videos, when you want complete control over your deployment environment."}]},{"type":"paragraph","content":[{"type":"text","text":"That''s it. We now have a fully functional Zitadel instance, we running on Zitadel Cloud. It took us less than five minutes. No Docker, no Kubernetes. Not even a terminal. In the next video, we''ll set up our first project and start to show you how to build your entire identity and authentication pipeline around Zitadel. The choice is yours, pick, what makes sense? Get your Zitadel deployed. And now it''s time to start building something great."}]}]}', 1790105224000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/06-first-application', 'complete-guide-zitadel', '06-first-application', 'first-application', 'Your First Application', 'Learn how to configure your first application in the Zitadel console, hook it up to a sample application, and inspect the JWT claims. We''ll cover the PKCE flow, token introspection, and adding user roles.', NULL, NULL, NULL, NULL, 'Getting Started', 6, '{"id":"g4uh2a6tw6koxe1d2ywrftyr","thumbnailUrl":"https://content.rawkode.academy/videos/g4uh2a6tw6koxe1d2ywrftyr/thumbnail.jpg"}', NULL, NULL, 1752624000, 0, '["rawkode"]', '[{"title":"OAuth PKCE Demo Application","description":"Interactive OAuth PKCE flow demonstration - Enter your Zitadel instance URL and client ID to test authentication","type":"embed","embedConfig":{"container":"webcontainer","src":"oauth-pkce-demo","height":"800px","width":"100%","import":{"localDir":"complete-guide-zitadel/oauth-pkce-demo"},"startCommand":"npm run dev"},"category":"code"}]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hello, welcome back. So far we''ve covered how to install and get Zitadel ready. I think it''s about time we take a look at how to actually make it work and integrate with your applications. So in this video we are gonna take a look at the Zitadel console, configure our first application, and get it hooked up to the point where we can log in and visualize the claims of our JWT token."}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s have some fun."}]},{"type":"heading","attrs":{"level":2,"id":"creating-your-first-application"},"content":[{"type":"text","text":"Creating Your First Application"}]},{"type":"paragraph","content":[{"type":"text","text":"The first thing we''re gonna do is click "},{"type":"text","text":"Create an application","marks":[{"type":"bold"}]},{"type":"text","text":". This guides us through creating our first project. I''ll call this "},{"type":"text","text":"Rawkode Academy","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Now you can select that you have some sort of front end framework. I''ll click "},{"type":"text","text":"React","marks":[{"type":"bold"}]},{"type":"text","text":". This is just telling us we''re going to use the PKCE flow. I''ll cover more about that in just a moment, but this is the recommended, preferred, most secure way to handle OIDC within your application."}]},{"type":"paragraph","content":[{"type":"text","text":"We then need to provide a redirect URL that is allowed to go through our flow. Because we''re working on a local application today, we can leave this as a default "},{"type":"text","text":"localhost:3000/callback","marks":[{"type":"code"}]},{"type":"text","text":", although we will have to modify that shortly."}]},{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Create","marks":[{"type":"bold"}]},{"type":"text","text":", and now we have our first project and application configured. A project can house one or more applications, meaning you can use the same project across mobile, web, server, CLIs, et cetera."}]},{"type":"paragraph","content":[{"type":"text","text":"In order to make this work with our application, we''ll need to go to "},{"type":"text","text":"URLs","marks":[{"type":"bold"}]},{"type":"text","text":" where we can get the discovery endpoint. We copy this, and this endpoint contains everything that you need to configure any OIDC application."}]},{"type":"heading","attrs":{"level":2,"id":"understanding-pkce"},"content":[{"type":"text","text":"Understanding PKCE"}]},{"type":"paragraph","content":[{"type":"text","text":"PKCE (Proof Key for Code Exchange) is a security extension for OAuth 2.0 that prevents authorization code interception attacks. It''s essential for public clients, like single-page applications and mobile applications that can''t securely store client secrets."}]},{"type":"paragraph","content":[{"type":"text","text":"Here is how PKCE works:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your application generates a cryptographically random "},{"type":"text","text":"code verifier","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It then creates a "},{"type":"text","text":"code challenge","marks":[{"type":"bold"}]},{"type":"text","text":" by applying a SHA256 hash to this verifier and Base64 URL encoding the result."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When initiating the authorization request, your app sends a code challenge and challenge method to the authorization server."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The user authenticates and grants permission. The authorization server returns an authorization code to your redirect URL."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your application can then exchange this code for tokens, but crucially, it must include the original "},{"type":"text","text":"code verifier","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The authorization server verifies that the code verifier matches the challenge it received earlier."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re working on a web application, you would typically have to provide a client ID and a client secret. For front-end applications, the PKCE flow is just a lot easier as you don''t have to worry about passing that secret material."}]},{"type":"heading","attrs":{"level":2,"id":"integrating-with-a-sample-app"},"content":[{"type":"text","text":"Integrating with a Sample App"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s run "},{"type":"text","text":"bun run dev","marks":[{"type":"code"}]},{"type":"text","text":" and refresh our application. The code for this will be available in a resources section below."}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s click "},{"type":"text","text":"Login","marks":[{"type":"bold"}]},{"type":"text","text":" and our application asks for our OIDC well-known configuration URL and our OAuth client ID. We can get the client ID from the application configuration page."}]},{"type":"paragraph","content":[{"type":"text","text":"After pasting them in, you might see an error about the redirect URI. This is a common issue. Because I''ve put together a very simple single-page application, we just need to modify our redirect URL to only be "},{"type":"text","text":"localhost:3000","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"After correcting that, we can log in and we are presented with our token introspection page."}]},{"type":"heading","attrs":{"level":2,"id":"token-introspection-and-roles"},"content":[{"type":"text","text":"Token Introspection and Roles"}]},{"type":"paragraph","content":[{"type":"text","text":"The first thing we have is our access token, and the second thing we have is our ID token. The ID token can be decoded to give us claims. We can see here that we have the issuer, the subject, the audience, an expiration, and the client ID."}]},{"type":"paragraph","content":[{"type":"text","text":"At the moment, there are no user roles. Let''s add some."}]},{"type":"paragraph","content":[{"type":"text","text":"From the console, I have added two roles to this project, grouped into "},{"type":"text","text":"C-Suite","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Forge","marks":[{"type":"code"}]},{"type":"text","text":". You can add roles as you wish. I can then go to "},{"type":"text","text":"Authorizations","marks":[{"type":"bold"}]},{"type":"text","text":" and assign these roles to my user for the project."}]},{"type":"paragraph","content":[{"type":"text","text":"If we go back to our web application and log in again, we get a new token. The decoded claims are bigger, and we can now see the roles assigned to our user."}]},{"type":"heading","attrs":{"level":2,"id":"required-configuration"},"content":[{"type":"text","text":"Required Configuration"}]},{"type":"paragraph","content":[{"type":"text","text":"For this to work, we do have to configure a few things within the project and the organization."}]},{"type":"paragraph","content":[{"type":"text","text":"In our React application''s "},{"type":"text","text":"Token Settings","marks":[{"type":"bold"}]},{"type":"text","text":", you''ll see that we have "},{"type":"text","text":"User Roles","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"User Info inside ID Token","marks":[{"type":"bold"}]},{"type":"text","text":" enabled. This makes it easy to debug and print that information to the UI. If you don''t have this, your application can just as easily contact the user info endpoint to get this information once it has the authentication token."}]},{"type":"paragraph","content":[{"type":"text","text":"Also, within the organization''s "},{"type":"text","text":"Login Settings","marks":[{"type":"bold"}]},{"type":"text","text":", we need to make sure that "},{"type":"text","text":"User Registration","marks":[{"type":"bold"}]},{"type":"text","text":" is allowed. This is disabled by default, so you will have to turn this on when you create your new Zitadel instance."}]},{"type":"paragraph","content":[{"type":"text","text":"In subsequent videos, we''re gonna take a look at turning on SSO and OAuth authentication, allowing our users to sign in with their own accounts rather than Zitadel provisioned users. We will also take a look at the simple email and password user registration flow soon, too."}]}]}', 1764608082000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/07-astro-integration', 'complete-guide-zitadel', '07-astro-integration', 'astro-integration', 'Integrating with an Astro Application', 'Learn how to integrate Zitadel with an Astro application, configure authentication, and manage user sessions. We''ll cover the PKCE flow, token introspection, and adding user roles.', NULL, NULL, NULL, NULL, 'Integrating with Your Applications', 7, '{"id":"nthmea2xnisnupheby8udwzx"}', NULL, NULL, 1753228800, 0, '["rawkode"]', '[{"title":"Arctic OAuth Library","description":"A TypeScript OAuth 2.0 library for Node.js","type":"url","url":"https://arcticjs.dev/","category":"other"},{"title":"Astro Authentication Guide","description":"Official Astro documentation on authentication","type":"url","url":"https://docs.astro.build/en/guides/authentication/","category":"other"},{"title":"PKCE Flow Explained","description":"Understanding the PKCE authorization flow","type":"url","url":"https://oauth.net/2/pkce/","category":"other"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"building-on-previous-knowledge"},"content":[{"type":"text","text":"Building on Previous Knowledge"}]},{"type":"paragraph","content":[{"type":"text","text":"In the previous video, we set up a basic application that could authenticate with Zitadel and visualize the JWT. Now we''re taking it a step further by integrating Zitadel into a real web application using Astro."}]},{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"This tutorial uses Astro, but the concepts apply to most web frameworks. We''ll cover other frameworks like Remix, Next.js, and SvelteKit in upcoming videos."}]}]},{"type":"heading","attrs":{"level":2,"id":"what-well-build"},"content":[{"type":"text","text":"What We''ll Build"}]},{"type":"paragraph","content":[{"type":"text","text":"In this tutorial, we''ll:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set up an Astro application with server-side rendering"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure Zitadel OAuth with PKCE flow"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement login and callback endpoints"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Handle JWT tokens and user sessions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Display user information after authentication"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"prerequisites"},"content":[{"type":"text","text":"Prerequisites"}]},{"type":"paragraph","content":[{"type":"text","text":"Before starting, make sure you have:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An Astro application (created with "},{"type":"text","text":"bun create astro@latest","marks":[{"type":"code"}]},{"type":"text","text":")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A Zitadel instance (Cloud or self-hosted)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Basic understanding of OAuth 2.0 and PKCE"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"setting-up-dependencies"},"content":[{"type":"text","text":"Setting Up Dependencies"}]},{"type":"paragraph","content":[{"type":"text","text":"Install Arctic for OAuth helpers, the JWT decoder used below, and the ID-token claim types:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"bun add arctic @oslojs/jwt\nbun add -d oidc-client-ts"}]},{"type":"paragraph","content":[{"type":"text","text":"Arctic handles all the heavy lifting for OAuth and OIDC flows, making our integration straightforward."}]},{"type":"heading","attrs":{"level":2,"id":"environment-configuration"},"content":[{"type":"text","text":"Environment Configuration"}]},{"type":"paragraph","content":[{"type":"text","text":"Create an "},{"type":"text","text":".envrc","marks":[{"type":"code"}]},{"type":"text","text":" file (or "},{"type":"text","text":".env","marks":[{"type":"code"}]},{"type":"text","text":" if you prefer) with your Zitadel configuration:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"export ZITADEL_CLIENT_ID=\"your-client-id\"\nexport ZITADEL_URL=\"https://your-instance.zitadel.cloud\""}]},{"type":"aside","attrs":{"variant":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"With PKCE, there''s no client secret to manage! Your client ID is safe to commit to version control."}]}]},{"type":"heading","attrs":{"level":2,"id":"configuring-astro"},"content":[{"type":"text","text":"Configuring Astro"}]},{"type":"paragraph","content":[{"type":"text","text":"Update your "},{"type":"text","text":"astro.config.mjs","marks":[{"type":"code"}]},{"type":"text","text":" to enable server-side rendering and configure environment variables:"}]},{"type":"codeBlock","attrs":{"language":"javascript","title":null,"meta":null},"content":[{"type":"text","text":"import { defineConfig } from ''astro/config'';\n\nexport default defineConfig({\n  output: ''server'',\n  env: {\n    schema: {\n      ZITADEL_URL: {\n        type: ''string'',\n        context: ''server'',\n        access: ''public'',\n      },\n      ZITADEL_CLIENT_ID: {\n        type: ''string'',\n        context: ''server'',\n        access: ''public'',\n      },\n    },\n    validateSecrets: true,\n  },\n});"}]},{"type":"heading","attrs":{"level":2,"id":"creating-the-zitadel-integration"},"content":[{"type":"text","text":"Creating the Zitadel Integration"}]},{"type":"paragraph","content":[{"type":"text","text":"Create a "},{"type":"text","text":"lib/zitadel.ts","marks":[{"type":"code"}]},{"type":"text","text":" file to handle the OAuth flow:"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import { ZITADEL_URL, ZITADEL_CLIENT_ID } from ''astro:env/server'';\nimport { generateCodeChallenge, generateState } from ''arctic'';\nimport { decodeJWT } from ''@oslojs/jwt'';\nimport type { IdTokenClaims } from ''oidc-client-ts'';\n\nexport class Zitadel {\n  private authorizationEndpoint: string;\n  private tokenEndpoint: string;\n  private redirectURI: string;\n\n  constructor() {\n    this.authorizationEndpoint = `${ZITADEL_URL}/oauth/v2/authorize`;\n    this.tokenEndpoint = `${ZITADEL_URL}/oauth/v2/token`;\n    this.redirectURI = ''http://localhost:4321/api/auth/callback'';\n  }\n\n  async createAuthorizationURL(state: string, codeChallenge: string, scopes: string[]): Promise<URL> {\n    const url = new URL(this.authorizationEndpoint);\n    url.searchParams.set(''response_type'', ''code'');\n    url.searchParams.set(''client_id'', ZITADEL_CLIENT_ID);\n    url.searchParams.set(''redirect_uri'', this.redirectURI);\n    url.searchParams.set(''state'', state);\n    url.searchParams.set(''scope'', scopes.join('' ''));\n    url.searchParams.set(''code_challenge_method'', ''S256'');\n    url.searchParams.set(''code_challenge'', codeChallenge);\n    return url;\n  }\n\n  async validateAuthorizationCode(code: string, codeVerifier: string) {\n    const response = await fetch(this.tokenEndpoint, {\n      method: ''POST'',\n      headers: {\n        ''Content-Type'': ''application/x-www-form-urlencoded'',\n      },\n      body: new URLSearchParams({\n        grant_type: ''authorization_code'',\n        client_id: ZITADEL_CLIENT_ID,\n        redirect_uri: this.redirectURI,\n        code,\n        code_verifier: codeVerifier,\n      }),\n    });\n\n    const tokens = await response.json();\n\n    // Optionally decode the ID token to get user claims\n    if (tokens.id_token) {\n      const claims = decodeJWT(tokens.id_token) as IdTokenClaims;\n      return { ...tokens, claims };\n    }\n\n    return tokens;\n  }\n}"}]},{"type":"heading","attrs":{"level":2,"id":"implementing-authentication-endpoints"},"content":[{"type":"text","text":"Implementing Authentication Endpoints"}]},{"type":"heading","attrs":{"level":3,"id":"sign-in-endpoint"},"content":[{"type":"text","text":"Sign-in Endpoint"}]},{"type":"paragraph","content":[{"type":"text","text":"Create "},{"type":"text","text":"pages/api/auth/signin.ts","marks":[{"type":"code"}]},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import type { APIRoute } from ''astro'';\nimport { generateState, generateCodeChallenge } from ''arctic'';\nimport { Zitadel } from ''@/lib/zitadel'';\n\nexport const prerender = false;\n\nexport const GET: APIRoute = async ({ cookies, redirect }) => {\n  const zitadel = new Zitadel();\n  const state = generateState();\n  const codeVerifier = generateCodeChallenge();\n  const codeChallenge = await generateCodeChallenge(codeVerifier);\n\n  // Store state and verifier in cookies for validation\n  cookies.set(''state'', state, {\n    httpOnly: true,\n    secure: import.meta.env.PROD,\n    sameSite: ''lax'',\n    maxAge: 60 * 10, // 10 minutes\n  });\n\n  cookies.set(''code_verifier'', codeVerifier, {\n    httpOnly: true,\n    secure: import.meta.env.PROD,\n    sameSite: ''lax'',\n    maxAge: 60 * 10,\n  });\n\n  const authUrl = await zitadel.createAuthorizationURL(\n    state,\n    codeChallenge,\n    [''openid'', ''profile'', ''email'']\n  );\n\n  return redirect(authUrl.toString());\n};"}]},{"type":"heading","attrs":{"level":3,"id":"callback-endpoint"},"content":[{"type":"text","text":"Callback Endpoint"}]},{"type":"paragraph","content":[{"type":"text","text":"Create "},{"type":"text","text":"pages/api/auth/callback.ts","marks":[{"type":"code"}]},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import type { APIRoute } from ''astro'';\nimport { Zitadel } from ''@/lib/zitadel'';\n\nexport const prerender = false;\n\nexport const GET: APIRoute = async ({ url, cookies, redirect }) => {\n  const code = url.searchParams.get(''code'');\n  const state = url.searchParams.get(''state'');\n\n  if (!code || !state) {\n    return new Response(''Invalid request'', { status: 400 });\n  }\n\n  const storedState = cookies.get(''state'')?.value;\n  const codeVerifier = cookies.get(''code_verifier'')?.value;\n\n  if (!storedState || !codeVerifier || state !== storedState) {\n    return new Response(''Invalid state'', { status: 400 });\n  }\n\n  // Clear temporary cookies\n  cookies.delete(''state'');\n  cookies.delete(''code_verifier'');\n\n  try {\n    const zitadel = new Zitadel();\n    const tokens = await zitadel.validateAuthorizationCode(code, codeVerifier);\n\n    // Store tokens in secure cookies\n    cookies.set(''access_token'', tokens.access_token, {\n      httpOnly: true,\n      secure: import.meta.env.PROD,\n      sameSite: ''lax'',\n      maxAge: tokens.expires_in,\n    });\n\n    if (tokens.refresh_token) {\n      cookies.set(''refresh_token'', tokens.refresh_token, {\n        httpOnly: true,\n        secure: import.meta.env.PROD,\n        sameSite: ''lax'',\n        maxAge: 60 * 60 * 24 * 30, // 30 days\n      });\n    }\n\n    return redirect(''/'');\n  } catch (error) {\n    console.error(''Authentication error:'', error);\n    return new Response(''Authentication failed'', { status: 500 });\n  }\n};"}]},{"type":"heading","attrs":{"level":2,"id":"connecting-the-login-button"},"content":[{"type":"text","text":"Connecting the Login Button"}]},{"type":"paragraph","content":[{"type":"text","text":"Update your login button to trigger the authentication flow:"}]},{"type":"codeBlock","attrs":{"language":"astro","title":null,"meta":null},"content":[{"type":"text","text":"<a href=\"/api/auth/signin\">Login with Zitadel</a>"}]},{"type":"heading","attrs":{"level":2,"id":"testing-the-integration"},"content":[{"type":"text","text":"Testing the Integration"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click the login button"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You''ll be redirected to Zitadel''s authentication page"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Log in or register a new account"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After successful authentication, you''ll be redirected back to your application"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check your browser''s developer tools to see the stored tokens"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"managing-multiple-accounts"},"content":[{"type":"text","text":"Managing Multiple Accounts"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel has excellent multi-account support. Users can:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Switch between different accounts seamlessly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Register new accounts during the login flow"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manage their profiles and settings"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"As an administrator, you can:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"View and manage all users in the Zitadel console"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Verify email addresses"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reset passwords"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure multi-factor authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set up roles and permissions"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"next-steps"},"content":[{"type":"text","text":"Next Steps"}]},{"type":"paragraph","content":[{"type":"text","text":"Now that we have basic authentication working, in future videos we''ll explore:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Role-Based Access Control (RBAC)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Refresh token handling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User profile management"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Social login providers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Advanced authorization patterns"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"summary"},"content":[{"type":"text","text":"Summary"}]},{"type":"paragraph","content":[{"type":"text","text":"Integrating Zitadel with Astro is straightforward thanks to:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The PKCE flow eliminating the need for client secrets"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Arctic library handling OAuth complexity"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Astro''s built-in support for server-side rendering and API routes"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"You can reuse the "},{"type":"text","text":"Zitadel","marks":[{"type":"code"}]},{"type":"text","text":" class across multiple projects or publish it as a package for your team."}]}]}', 1790105224000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/08-remix-integration', 'complete-guide-zitadel', '08-remix-integration', 'Remix-integration', 'Integrating with an Remix Application', 'Learn how to integrate Zitadel with an Remix application, configure authentication, and manage user sessions. We''ll cover the PKCE flow, token introspection, and adding user roles.', NULL, NULL, NULL, NULL, 'Integrating with Your Applications', 8, NULL, NULL, NULL, 1752710400, 1, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"paragraph"}]}', 1764608082000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/09-authentication-methods', 'complete-guide-zitadel', '09-authentication-methods', 'authentication-methods', 'Passwords, Passkeys, and MFA', 'Configure password policies, implement passwordless authentication with passkeys, and set up multi-factor authentication', NULL, NULL, NULL, NULL, 'Authentication', 9, '{"id":"pxdgreblk59hxyny139a7i8i","thumbnailUrl":"https://content.rawkode.academy/videos/pxdgreblk59hxyny139a7i8i/thumbnail.jpg"}', NULL, NULL, 1753833600, 0, '["rawkode"]', '[{"title":"Zitadel Authentication Methods","description":"Official documentation on authentication methods","type":"url","url":"https://zitadel.com/docs/guides/authentication","category":"documentation"},{"title":"WebAuthn & Passkeys Guide","description":"Understanding passwordless authentication","type":"url","url":"https://webauthn.guide/","category":"documentation"},{"title":"FIDO Alliance","description":"Standards for passwordless authentication","type":"url","url":"https://fidoalliance.org/","category":"documentation"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"multiple-authentication-methods-in-zitadel"},"content":[{"type":"text","text":"Multiple Authentication Methods in Zitadel"}]},{"type":"paragraph","content":[{"type":"text","text":"In this video, we''re going to take a look at something very simple, but also important: allowing people to register and login to your application using Zitadel with multiple methods. We''ll cover username and password authentication, Passkeys, and explore the other options available in the Zitadel console."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started-with-identity-providers"},"content":[{"type":"text","text":"Getting Started with Identity Providers"}]},{"type":"paragraph","content":[{"type":"text","text":"When you first open your Zitadel Cloud console, you''ll find the default settings for your instance. If you click on "},{"type":"text","text":"Identity Providers","marks":[{"type":"bold"}]},{"type":"text","text":", you''ll see that there are no third-party setups initially - no Google, GitHub, or other providers configured yet."}]},{"type":"paragraph","content":[{"type":"text","text":"For third-party providers like GitHub, you can click on them to get the configuration details where you''ll need to add your client ID and secret. This setup is especially important when running your own Zitadel instance, as it''s often crucial to piggyback onto existing authentication providers. We''ll be covering social login providers in detail in the next video."}]},{"type":"heading","attrs":{"level":2,"id":"configuring-password-authentication"},"content":[{"type":"text","text":"Configuring Password Authentication"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s start with the basics: how can we allow people to log in with their username and password? And even better, can we enable passwordless Passkey-based login?"}]},{"type":"paragraph","content":[{"type":"text","text":"Good news: by default, passwordless login is enabled and supports:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fingerprint authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Security keys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Face ID"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Other biometric methods"}]}]}]},{"type":"aside","attrs":{"variant":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Important:","marks":[{"type":"bold"}]},{"type":"text","text":" Username and password authentication is NOT enabled by default in new Zitadel instances. You''ll need to manually enable this in your settings."}]}]},{"type":"heading","attrs":{"level":3,"id":"enabling-username-and-password-login"},"content":[{"type":"text","text":"Enabling Username and Password Login"}]},{"type":"paragraph","content":[{"type":"text","text":"To enable traditional password-based authentication:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to your instance''s default settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the "},{"type":"text","text":"Login Behavior and Security","marks":[{"type":"bold"}]},{"type":"text","text":" section"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable "},{"type":"text","text":"Username and Password","marks":[{"type":"bold"}]},{"type":"text","text":" authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check that "},{"type":"text","text":"User Registration","marks":[{"type":"bold"}]},{"type":"text","text":" is allowed"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Save","marks":[{"type":"bold"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll also find configuration options for:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password complexity requirements"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password lifetime policies"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Secret rotation settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Login and registration restrictions"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"understanding-organization-vs-instance-settings"},"content":[{"type":"text","text":"Understanding Organization vs Instance Settings"}]},{"type":"paragraph","content":[{"type":"text","text":"One crucial point that often trips up new users: Zitadel has a hierarchy of settings."}]},{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"There are "},{"type":"text","text":"default instance-wide settings","marks":[{"type":"bold"}]},{"type":"text","text":" that apply to all organizations when they have nothing set themselves or when they inherit from the instance. Each organization can also be configured independently with its own settings."}]}]},{"type":"paragraph","content":[{"type":"text","text":"For example, if you disable user registration at the instance level but it''s still enabled at the organization level, users can still register. Always check both levels when configuring authentication:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Instance Settings","marks":[{"type":"bold"}]},{"type":"text","text":": Default settings for your entire Zitadel instance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Organization Settings","marks":[{"type":"bold"}]},{"type":"text","text":": Can override instance defaults for specific organizations"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"user-registration-flow"},"content":[{"type":"text","text":"User Registration Flow"}]},{"type":"paragraph","content":[{"type":"text","text":"With registration enabled, here''s the typical user flow:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User navigates to the login page"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clicks "},{"type":"text","text":"Register","marks":[{"type":"bold"}]},{"type":"text","text":" to create a new account"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fills in the registration form:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Name"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Email address"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password (if password authentication is enabled)"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirms email address via verification code"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optionally sets up second factor authentication"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gains access to their user profile"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The entire process is handled by Zitadel''s built-in UI - you don''t need to build any custom forms initially."}]},{"type":"heading","attrs":{"level":2,"id":"adding-passwordless-authentication"},"content":[{"type":"text","text":"Adding Passwordless Authentication"}]},{"type":"paragraph","content":[{"type":"text","text":"Once a user has registered, they can add passwordless authentication methods:"}]},{"type":"heading","attrs":{"level":3,"id":"setting-up-a-passkey"},"content":[{"type":"text","text":"Setting Up a Passkey"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to "},{"type":"text","text":"Password and Security","marks":[{"type":"bold"}]},{"type":"text","text":" in the user profile"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Add Method","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Use my own device","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give the Passkey a descriptive name"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Follow your browser/device prompts to create the Passkey"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Passkey can be stored in:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your device''s secure enclave"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Password managers like 1Password or Bitwarden"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardware security keys"}]}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"After setting up a Passkey, users can log in without entering a password - they''ll just need to authenticate with their biometric or security key."}]},{"type":"heading","attrs":{"level":2,"id":"multi-factor-authentication-mfa"},"content":[{"type":"text","text":"Multi-Factor Authentication (MFA)"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel supports multiple second factors for enhanced security:"}]},{"type":"heading","attrs":{"level":3,"id":"totp-time-based-one-time-passwords"},"content":[{"type":"text","text":"TOTP (Time-based One-Time Passwords)"}]},{"type":"paragraph","content":[{"type":"text","text":"Users can scan a QR code with authenticator apps like:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Google Authenticator"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Microsoft Authenticator"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"1Password"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Authy"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"fido2webauthn-keys"},"content":[{"type":"text","text":"FIDO2/WebAuthn Keys"}]},{"type":"paragraph","content":[{"type":"text","text":"Hardware security keys provide the strongest second factor:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"YubiKey"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Google Titan"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Any FIDO2-compliant key"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"login-v2-and-custom-authentication-ui"},"content":[{"type":"text","text":"Login V2 and Custom Authentication UI"}]},{"type":"paragraph","content":[{"type":"text","text":"While Zitadel provides a complete authentication UI out of the box, you might want something more integrated with your application. That''s where Login V2 comes in."}]},{"type":"aside","attrs":{"variant":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Login V2 hooks into the Zitadel Session API, allowing you to build custom authentication flows while still leveraging Zitadel''s security features."}]}]},{"type":"paragraph","content":[{"type":"text","text":"To enable Login V2:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to "},{"type":"text","text":"Default Settings","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to "},{"type":"text","text":"Features","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scroll down to find "},{"type":"text","text":"Login V2","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable the feature"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"You can then either:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fork Zitadel''s TypeScript reference implementation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build your own implementation using the Session API directly"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll cover Login V2 in detail in an upcoming video, as there''s a lot to explore with custom authentication flows."}]},{"type":"heading","attrs":{"level":2,"id":"best-practices"},"content":[{"type":"text","text":"Best Practices"}]},{"type":"heading","attrs":{"level":3,"id":"for-development"},"content":[{"type":"text","text":"For Development"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start with username/password for simplicity"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable all authentication methods to test integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use Zitadel''s default UI to prototype quickly"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"for-production"},"content":[{"type":"text","text":"For Production"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable Passkeys for better user experience"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Require MFA for sensitive applications"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider disabling password authentication entirely for maximum security"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement proper password policies if passwords are required"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use organization-specific settings for multi-tenant applications"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"whats-next"},"content":[{"type":"text","text":"What''s Next?"}]},{"type":"paragraph","content":[{"type":"text","text":"In the next video, we''ll take a look at configuring third-party OAuth providers like GitHub and Google for social login. This allows users to authenticate with accounts they already have, reducing friction in the registration process."}]},{"type":"paragraph","content":[{"type":"text","text":"After that, we''ll dive deep into Login V2 and building custom authentication experiences that seamlessly integrate with your application''s design."}]},{"type":"heading","attrs":{"level":2,"id":"summary"},"content":[{"type":"text","text":"Summary"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel provides flexible authentication options out of the box:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traditional username and password"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern passwordless authentication with Passkeys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-factor authentication with TOTP and hardware keys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Customizable registration and login flows"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The key is understanding the settings hierarchy (instance vs organization) and choosing the right authentication methods for your use case. Start simple with the defaults, then customize as your requirements evolve."}]}]}', 1764608082000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/10-social-login-providers', 'complete-guide-zitadel', '10-social-login-providers', 'authentication-methods-oauth', 'Configuring OAuth Providers (Google, GitHub, etc.)', 'Integrate third-party OAuth providers like Google, GitHub, and Microsoft for social login, configure client IDs, secrets, and scopes', NULL, NULL, NULL, NULL, 'Authentication', 10, '{"id":"aaaag9oumw7ybfepfziq6e2b","thumbnailUrl":"https://content.rawkode.academy/videos/aaaag9oumw7ybfepfziq6e2b/thumbnail.jpg"}', NULL, NULL, 1752105600, 0, '["rawkode"]', '[{"title":"GitHub OAuth Apps Documentation","description":"Official guide for creating OAuth applications on GitHub","type":"url","url":"https://docs.github.com/en/developers/apps/building-oauth-apps","category":"documentation"},{"title":"Zitadel Identity Providers Guide","description":"Configure external identity providers in Zitadel","type":"url","url":"https://zitadel.com/docs/guides/identity-providers","category":"documentation"},{"title":"OAuth 2.0 Scopes","description":"Understanding OAuth scopes and permissions","type":"url","url":"https://oauth.net/2/scope/","category":"documentation"},{"title":"Zitadel Actions Documentation","description":"Learn about Zitadel Actions for customizing authentication flows","type":"url","url":"https://zitadel.com/docs/guides/actions","category":"documentation"}]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"connecting-zitadel-with-external-oauth-providers"},"content":[{"type":"text","text":"Connecting Zitadel with External OAuth Providers"}]},{"type":"paragraph","content":[{"type":"text","text":"Welcome back to the Complete Guide to Zitadel. In this video, we''ll explore how to connect your Zitadel instance to external OAuth providers, allowing users to log in using their existing accounts from services like GitHub, Google, Microsoft, and more."}]},{"type":"paragraph","content":[{"type":"text","text":"While this tutorial uses GitHub as the example, the principles apply to any OpenID Connect provider - whether that''s Google, Microsoft, Okta, Auth0, or any other service that supports OAuth 2.0."}]},{"type":"heading","attrs":{"level":2,"id":"understanding-identity-provider-configuration"},"content":[{"type":"text","text":"Understanding Identity Provider Configuration"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel offers two levels for configuring identity providers:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Instance Level (Default Settings)","marks":[{"type":"bold"}]},{"type":"text","text":": Providers configured here are inherited by all organizations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Organization Level","marks":[{"type":"bold"}]},{"type":"text","text":": Each organization can have its own identity provider configuration"}]}]}]},{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"For multi-tenant B2B applications, you''ll typically configure providers at the organization level to give each tenant control over their authentication methods."}]}]},{"type":"heading","attrs":{"level":2,"id":"setting-up-github-oauth"},"content":[{"type":"text","text":"Setting Up GitHub OAuth"}]},{"type":"heading","attrs":{"level":3,"id":"step-1-create-a-github-oauth-application"},"content":[{"type":"text","text":"Step 1: Create a GitHub OAuth Application"}]},{"type":"paragraph","content":[{"type":"text","text":"First, we need to create an OAuth application in GitHub:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to your GitHub Developer Settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"New OAuth App","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in the application details:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Application Name","marks":[{"type":"bold"}]},{"type":"text","text":": Your app name (e.g., \"Zitadel Demo\")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Homepage URL","marks":[{"type":"bold"}]},{"type":"text","text":": Your application URL"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Authorization callback URL","marks":[{"type":"bold"}]},{"type":"text","text":": Copy this from Zitadel''s setup screen"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Register application","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Note your "},{"type":"text","text":"Client ID","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Generate a new "},{"type":"text","text":"Client Secret","marks":[{"type":"bold"}]},{"type":"text","text":" (save this securely - you''ll only see it once!)"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"step-2-configure-github-in-zitadel"},"content":[{"type":"text","text":"Step 2: Configure GitHub in Zitadel"}]},{"type":"paragraph","content":[{"type":"text","text":"In the Zitadel console:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate to "},{"type":"text","text":"Organizations","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":"Your Organization","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":"Login and Access","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"Identity Providers","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":"Add Provider","marks":[{"type":"bold"}]},{"type":"text","text":" → "},{"type":"text","text":"GitHub","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter your GitHub OAuth app credentials:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Client ID","marks":[{"type":"bold"}]},{"type":"text","text":": From GitHub"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Client Secret","marks":[{"type":"bold"}]},{"type":"text","text":": From GitHub"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scopes","marks":[{"type":"bold"}]},{"type":"text","text":": Configure based on your needs"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure the provider settings"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"understanding-oauth-scopes"},"content":[{"type":"text","text":"Understanding OAuth Scopes"}]},{"type":"paragraph","content":[{"type":"text","text":"When configuring GitHub (or any OAuth provider), you need to specify which scopes your application requires. For GitHub:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"read:user","marks":[{"type":"code"}]},{"type":"text","text":" - Read access to user profile data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"user:email","marks":[{"type":"code"}]},{"type":"text","text":" - Access to user email addresses"}]}]}]},{"type":"aside","attrs":{"variant":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Always request the minimum scopes necessary for your application. This follows the principle of least privilege and builds user trust."}]}]},{"type":"paragraph","content":[{"type":"text","text":"For other providers, common scopes include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Google","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"openid","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"profile","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"email","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Microsoft","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"openid","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"profile","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"email","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"offline_access","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auth0","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"openid","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"profile","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"email","marks":[{"type":"code"}]}]}]}]},{"type":"heading","attrs":{"level":2,"id":"provider-configuration-options"},"content":[{"type":"text","text":"Provider Configuration Options"}]},{"type":"heading","attrs":{"level":3,"id":"display-name"},"content":[{"type":"text","text":"Display Name"}]},{"type":"paragraph","content":[{"type":"text","text":"This is what users will see on the login button (e.g., \"GitHub Demo\" or \"Sign in with GitHub\")"}]},{"type":"heading","attrs":{"level":3,"id":"account-creation"},"content":[{"type":"text","text":"Account Creation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatic creation","marks":[{"type":"bold"}]},{"type":"text","text":": Enable to automatically create Zitadel accounts for new users"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Account update","marks":[{"type":"bold"}]},{"type":"text","text":": Update user information from the provider on each login"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Account linking","marks":[{"type":"bold"}]},{"type":"text","text":": Merge accounts with matching email addresses"}]}]}]},{"type":"aside","attrs":{"variant":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Be careful with account linking by email. Only enable this if you trust the email verification process of your identity providers."}]}]},{"type":"heading","attrs":{"level":2,"id":"the-github-name-challenge"},"content":[{"type":"text","text":"The GitHub Name Challenge"}]},{"type":"paragraph","content":[{"type":"text","text":"GitHub presents a unique challenge: it doesn''t provide separate first and last name fields in its user profile. Instead, it returns a single "},{"type":"text","text":"name","marks":[{"type":"code"}]},{"type":"text","text":" field. Since Zitadel requires both first and last names for account creation, we need to handle this."}]},{"type":"heading","attrs":{"level":3,"id":"solution-zitadel-actions"},"content":[{"type":"text","text":"Solution: Zitadel Actions"}]},{"type":"paragraph","content":[{"type":"text","text":"Zitadel Actions allow you to customize the authentication flow. Here''s how to automatically split the GitHub name:"}]},{"type":"codeBlock","attrs":{"language":"javascript","title":null,"meta":null},"content":[{"type":"text","text":"function updateGitHubUser(ctx, api) {\n  // Check if this is a GitHub login\n  if (ctx.v1.externalIdp?.id !== ''YOUR_GITHUB_IDP_ID'') {\n    return;\n  }\n\n  // Get the full name from GitHub\n  const fullName = ctx.v1.externalIdp?.rawInfo?.name || '''';\n  \n  // Split the name intelligently\n  const parts = fullName.trim().split('' '');\n  \n  if (parts.length === 0) {\n    return;\n  }\n  \n  // Set first name and last name\n  if (parts.length === 1) {\n    api.v1.user.setFirstName(parts[0]);\n    api.v1.user.setLastName(''''); // Or use a placeholder\n  } else {\n    api.v1.user.setFirstName(parts[0]);\n    api.v1.user.setLastName(parts.slice(1).join('' ''));\n  }\n}"}]},{"type":"heading","attrs":{"level":3,"id":"implementing-the-action"},"content":[{"type":"text","text":"Implementing the Action"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to "},{"type":"text","text":"Actions","marks":[{"type":"bold"}]},{"type":"text","text":" in the Zitadel console"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click "},{"type":"text","text":"New Action","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Name it (e.g., \"Update GitHub User\")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paste the action code"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replace "},{"type":"text","text":"YOUR_GITHUB_IDP_ID","marks":[{"type":"code"}]},{"type":"text","text":" with your actual GitHub IDP ID (found in the URL)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Save the action"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a trigger for "},{"type":"text","text":"Post Authentication","marks":[{"type":"bold"}]}]}]}]},{"type":"heading","attrs":{"level":2,"id":"testing-the-integration"},"content":[{"type":"text","text":"Testing the Integration"}]},{"type":"paragraph","content":[{"type":"text","text":"Once configured:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Log out of Zitadel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to the login page"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You''ll see your new provider button (e.g., \"Sign in with GitHub\")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click it to authenticate"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Authorize the application in GitHub"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You''ll be redirected back to Zitadel and logged in"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"first-time-login-flow"},"content":[{"type":"text","text":"First-Time Login Flow"}]},{"type":"paragraph","content":[{"type":"text","text":"For new users:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"They authenticate with the external provider"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If account creation is automatic, Zitadel creates their account"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the action is configured, it processes user data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The user is logged in to your application"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"returning-user-flow"},"content":[{"type":"text","text":"Returning User Flow"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Click the provider button"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If still authenticated with the provider, immediate redirect"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Otherwise, authenticate with the provider"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return to your application"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"configuring-other-popular-providers"},"content":[{"type":"text","text":"Configuring Other Popular Providers"}]},{"type":"heading","attrs":{"level":3,"id":"google"},"content":[{"type":"text","text":"Google"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create a project in Google Cloud Console"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable Google+ API"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create OAuth 2.0 credentials"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add authorized redirect URI from Zitadel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure in Zitadel with scopes: "},{"type":"text","text":"openid profile email","marks":[{"type":"code"}]}]}]}]},{"type":"heading","attrs":{"level":3,"id":"microsoft-azure-ad"},"content":[{"type":"text","text":"Microsoft (Azure AD)"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Register an application in Azure Portal"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a redirect URI (Web platform)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create a client secret"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure in Zitadel with tenant information"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use scopes: "},{"type":"text","text":"openid profile email offline_access","marks":[{"type":"code"}]}]}]}]},{"type":"heading","attrs":{"level":3,"id":"auth0"},"content":[{"type":"text","text":"Auth0"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create an application in Auth0 Dashboard"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set callback URL from Zitadel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Note domain, client ID, and secret"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure in Zitadel with your Auth0 domain"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"multiple-identity-providers"},"content":[{"type":"text","text":"Multiple Identity Providers"}]},{"type":"paragraph","content":[{"type":"text","text":"You can configure multiple identity providers simultaneously:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Users can choose their preferred login method"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accounts can be linked if emails match (when configured)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Different organizations can have different provider sets"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Providers can be enabled/disabled without data loss"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"actions-v2-preview"},"content":[{"type":"text","text":"Actions v2 Preview"}]},{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Zitadel is developing Actions v2, which provides more sophisticated event handling and function capabilities. We''ll cover this in detail in a future video."}]}]},{"type":"heading","attrs":{"level":2,"id":"security-considerations"},"content":[{"type":"text","text":"Security Considerations"}]},{"type":"heading","attrs":{"level":3,"id":"client-secret-management"},"content":[{"type":"text","text":"Client Secret Management"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store secrets securely"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rotate secrets regularly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Never commit secrets to version control"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use environment variables or secret management tools"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"scope-management"},"content":[{"type":"text","text":"Scope Management"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Request minimal necessary scopes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review scope requirements regularly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Document why each scope is needed"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider user privacy implications"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"account-linking"},"content":[{"type":"text","text":"Account Linking"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only link accounts with verified emails"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider the trust level of each provider"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement additional verification for sensitive operations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Log account linking events for audit trails"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"troubleshooting-common-issues"},"content":[{"type":"text","text":"Troubleshooting Common Issues"}]},{"type":"heading","attrs":{"level":3,"id":"external-user-not-found"},"content":[{"type":"text","text":"\"External user not found\""}]},{"type":"paragraph","content":[{"type":"text","text":"This occurs when:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatic account creation is disabled"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The action fails to set required fields"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"There''s a mismatch in expected user data"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"redirect-uri-mismatch"},"content":[{"type":"text","text":"Redirect URI Mismatch"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ensure the callback URL in your provider matches exactly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check for trailing slashes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Verify HTTP vs HTTPS"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm the correct Zitadel instance URL"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"missing-user-information"},"content":[{"type":"text","text":"Missing User Information"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the requested scopes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Verify the provider returns expected fields"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use actions to transform or supplement data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review provider-specific documentation"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"best-practices"},"content":[{"type":"text","text":"Best Practices"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start Simple","marks":[{"type":"bold"}]},{"type":"text","text":": Begin with one provider and expand"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test Thoroughly","marks":[{"type":"bold"}]},{"type":"text","text":": Test new user registration and returning user flows"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Document Configuration","marks":[{"type":"bold"}]},{"type":"text","text":": Keep records of client IDs, scopes, and settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitor Usage","marks":[{"type":"bold"}]},{"type":"text","text":": Track which providers users prefer"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plan for Failures","marks":[{"type":"bold"}]},{"type":"text","text":": Have fallback authentication methods"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Regular Audits","marks":[{"type":"bold"}]},{"type":"text","text":": Review provider configurations and permissions"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"summary"},"content":[{"type":"text","text":"Summary"}]},{"type":"paragraph","content":[{"type":"text","text":"Connecting external OAuth providers to Zitadel is straightforward:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create an OAuth application with your provider"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure the provider in Zitadel with credentials and scopes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Handle any provider-specific quirks with Actions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test the complete authentication flow"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"With just a few clicks, you can offer users authentication through GitHub, Google, Microsoft, LinkedIn, Stack Overflow, and dozens of other providers. This reduces friction in the registration process and lets users leverage their existing accounts."}]},{"type":"paragraph","content":[{"type":"text","text":"In the next video, we''ll explore more advanced authentication patterns and dive deeper into Zitadel Actions for customizing your authentication flows."}]}]}', 1764608082000);
