INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('complete-guide-zitadel/user-management-registration', 'complete-guide-zitadel', 'user-management-registration', 'user-management-registration', 'User Management and Registration Flows', 'Create and manage users, configure self-registration, implement custom registration flows, and understand user lifecycles', NULL, NULL, NULL, NULL, 'User Management', 99, NULL, NULL, NULL, 1752105600, 1, '["rawkode"]', NULL, '{"type":"doc","content":[{"type":"paragraph"}]}', 1764608082000);
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('rust-for-the-rusty/01-introduction', 'rust-for-the-rusty', '01-introduction', 'introduction', 'Introduction', 'Rust for the Rusty: a practical re-introduction to Rust for busy engineers and brave beginners who want modern, confident Rust.
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/01-introduction', 'teleport-for-kubernetes', '01-introduction', 'introduction', 'Introduction to Teleport for Kubernetes', 'Understand the problem with default Kubernetes access — long-lived credentials, no revocation, and audit gaps — and how Teleport solves it with short-lived certificates, real identities, and full audit logging.
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/02-deploying-teleport-cluster', 'teleport-for-kubernetes', '02-deploying-teleport-cluster', 'deploying-teleport-cluster', 'Deploying a Teleport Cluster on Kubernetes', 'Deploy a working Teleport cluster on Kubernetes using Helm, with TLS certificates via cert-manager and an admin user ready to log in.
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/03-identity-based-access-rbac', 'teleport-for-kubernetes', '03-identity-based-access-rbac', 'identity-based-access-rbac', 'Identity-Based User Access & RBAC', 'Replace manually configured users with GitHub SSO authentication, map GitHub teams to Teleport roles, and access your Kubernetes clusters with short-lived certificates tied to real identities.
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/04-two-layer-rbac-boundaries', 'teleport-for-kubernetes', '04-two-layer-rbac-boundaries', 'two-layer-rbac-boundaries', 'Two-Layer RBAC with Teleport Boundaries', 'Build a two-layer RBAC model where Teleport controls which Kubernetes groups a user''s certificate carries, and Kubernetes RBAC controls what those groups can do — with deny rules creating hard security boundaries.
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/05-just-in-time-access', 'teleport-for-kubernetes', '05-just-in-time-access', 'just-in-time-access', 'Just-in-Time Access for Incidents', 'Implement just-in-time access requests so nobody has standing admin privileges — when paged at 3 AM, engineers request temporary elevated access that is peer-reviewed and time-bounded.
INSERT INTO `course_modules` (`id`, `course_id`, `slug`, `frontmatter_slug`, `title`, `description`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `section`, `sort_order`, `video`, `duration`, `difficulty`, `published_at`, `draft`, `authors`, `resources`, `body`, `updated_at`) VALUES ('teleport-for-kubernetes/06-auditing-and-session-recording', 'teleport-for-kubernetes', '06-auditing-and-session-recording', 'auditing-and-session-recording', 'Auditing and Session Recording', 'Explore Teleport''s audit logging, session recording, and live session joining — every kubectl command, every exec session, tied to a real identity with full playback capabilities.
INSERT INTO `learning_paths` (`id`, `title`, `description`, `difficulty`, `estimated_duration`, `prerequisites`, `technologies`, `published_at`, `authors`, `body`, `updated_at`) VALUES ('build-your-first-kubernetes-developer-platform', 'Build Your First Kubernetes Developer Platform', 'Move from GUI-driven cluster management to platform APIs, golden-path deployments, and automated operations. This path assembles modern tools that let you offer a polished developer experience on Kubernetes without drowning in YAML.', 'beginner', 428, '["Comfortable using a command-line interface and Git.","Basic understanding of containers and Kubernetes primitives (Pods, Deployments, Services).","Access to a Kubernetes cluster (local or cloud) where you can install Helm charts and custom controllers.","Familiarity with Visual Studio Code or another code editor.","Exposure to CI/CD or GitOps workflows is helpful."]', '["kubernetes","portainer","devstand","crossplane","waypoint","robusta","prometheus"]', 1759276800, '["rawkode"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Move from UI-driven Kubernetes operations to opinionated platform APIs, golden-path deployments, and automated incident response. Each stop introduces a production-ready building block you can stitch together into a developer platform."}]},{"type":"heading","attrs":{"level":2,"id":"learning-objectives"},"content":[{"type":"text","text":"Learning Objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apply guardrails and RBAC to simplify day-one cluster onboarding for teams."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Model applications with reusable templates that compile to standard Kubernetes manifests."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expose cloud infrastructure as platform APIs through Crossplane compositions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deliver a consistent build → deploy → release workflow with HashiCorp Waypoint."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enrich Prometheus alerts so platform engineers and developers can close the loop on incidents quickly."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"videos-in-this-path"},"content":[{"type":"text","text":"Videos in This Path"}]},{"type":"heading","attrs":{"level":3,"id":"1-hands-on-introduction-to-portainer"},"content":[{"type":"text","text":"1. "},{"type":"text","text":"Hands-on Introduction to Portainer","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-portainer","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Portainer gives you a \"manager of managers\" interface so teams can safely explore Kubernetes before you expose lower-level tools."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Understand the core value proposition of Portainer for simplifying container management."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Describe how Portainer provides a unified interface for managing diverse environments like Kubernetes, Docker, and Nomad."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apply policies, RBAC, and guardrails that keep self-service access secure."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deploy a containerized application from the Portainer UI to demonstrate a fast path to value."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Portainer has grown into a universal management plane for multi-cluster and edge environments."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Built-in guardrails, policy enforcement, and centralized RBAC prevent common misconfigurations while keeping workflows approachable."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"2-hands-on-introduction-to-devstand"},"content":[{"type":"text","text":"2. "},{"type":"text","text":"Hands-on Introduction to DevStand","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-devstand","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" DevStand turns platform patterns into Jsonnet templates and a drag-and-drop VS Code experience, closing the gap between application design and Kubernetes delivery."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recognize the Kubernetes pain points DevStand abstracts for application developers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use Jsonnet-powered templates to replace verbose Kubernetes YAML."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assemble a microservice architecture visually inside VS Code and generate manifests."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export a single DevStand configuration that compiles to version-controlled Kubernetes resources."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DevStand delivers a PaaS-like experience on any Kubernetes cluster through reusable building blocks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Jsonnet source of truth keeps complex app definitions portable and reviewable while the visual canvas accelerates developer onboarding."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"3-introduction-to-crossplane"},"content":[{"type":"text","text":"3. "},{"type":"text","text":"Introduction to Crossplane","marks":[{"type":"link","attrs":{"href":"/watch/introduction-to-crossplane","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Before you hand developers infrastructure APIs, you need a universal control plane that speaks Kubernetes and cloud. Crossplane provides the foundation."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain how Crossplane extends the Kubernetes API to manage external infrastructure."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare Crossplane’s continuous reconciliation model with on-demand IaC tools like Terraform."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Crossplane, add a cloud provider, and explore Composite Resource Definitions (XRDs)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Design simplified platform APIs that hide cloud complexity behind custom resources."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Crossplane turns Kubernetes into a universal control plane so you can manage cloud resources with the same GitOps workflows as workloads."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Continuous reconciliation and compositions keep infrastructure drift-free while enforcing platform policy."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"4-crossplane-in-action"},"content":[{"type":"text","text":"4. "},{"type":"text","text":"Crossplane in Action","marks":[{"type":"link","attrs":{"href":"/watch/crossplane-in-action","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" This follow-up demonstrates how to package your abstractions into real platform building blocks that developers can consume safely."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Provision cloud infrastructure using standard Kubernetes manifests and Crossplane Compositions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apply opinionated platform APIs that bundle best practices into a single custom resource."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Observe Crossplane’s reconciliation loop correcting drift and maintaining desired state."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Map RBAC and credential boundaries so teams can request infrastructure without direct cloud access."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Crossplane compositions let platform teams encode golden paths that stay aligned with policy and security requirements."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Treating infrastructure as Kubernetes objects unlocks native integrations with GitOps, policy engines, and observability stacks."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"5-hands-on-introduction-to-waypoint"},"content":[{"type":"text","text":"5. "},{"type":"text","text":"Hands-on Introduction to Waypoint","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-waypoint","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Waypoint standardizes the build → deploy → release cycle, whether teams target Lambda, Kubernetes, or another runtime—perfect for platform engineers who need a portable workflow."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install the Waypoint server locally and on Kubernetes to back your platform workflows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define applications in "},{"type":"text","text":"waypoint.hcl","marks":[{"type":"code"}]},{"type":"text","text":" and plug into existing YAML or Cloud Native Buildpacks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run automated deployments to Kubernetes and AWS Lambda from the same configuration."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Separate deployment from release to enable progressive delivery strategies."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"waypoint up","marks":[{"type":"code"}]},{"type":"text","text":" creates a consistent developer experience across multiple execution environments."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plugins and the distinct release phase give platform teams fine-grained control without rewriting pipelines per environment."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"6-monitoring-kubernetes-with-prometheus--robusta"},"content":[{"type":"text","text":"6. "},{"type":"text","text":"Monitoring Kubernetes with Prometheus & Robusta","marks":[{"type":"link","attrs":{"href":"/watch/monitoring-kubernetes-with-prometheus-and-robusta","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" A platform is only as good as its day-two operations. Robusta enriches Prometheus alerts so frontline engineers get context, not just noise."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Robusta alongside Prometheus using Helm and connect it to Alertmanager."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enrich alerts with logs, graphs, and timelines that accelerate troubleshooting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Customize Robusta enrichers to collect runbook data for recurring production issues."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Navigate the Robusta SaaS UI for multi-cluster visibility and faster MTTR."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Standard Prometheus alerts lack context; Robusta automates evidence gathering to reduce alert fatigue."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Runbook automation keeps developers productive and closes the loop between platform engineers and the teams they support."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"where-to-go-next"},"content":[{"type":"text","text":"Where to Go Next"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine DevStand blueprints and Crossplane compositions into a single GitOps repository so application and infrastructure definitions travel together."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add Robusta KRR to surface resource efficiency recommendations alongside alert enrichment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pilot Waypoint pipelines with a small product team, then roll them out across environments once the workflow meets internal guardrails."}]}]}]}]}', 1790105224000);
INSERT INTO `learning_paths` (`id`, `title`, `description`, `difficulty`, `estimated_duration`, `prerequisites`, `technologies`, `published_at`, `authors`, `body`, `updated_at`) VALUES ('gitops-landscape', 'GitOps Landscape', 'Build a GitOps-first operating model. This path layers modern packaging, reconciliation, and developer experience tooling—Timoni, Kluctl, FluxCD, Gimlet, and Sveltos—so you can run fleets with confidence.', 'advanced', 432, '["Comfortable with Kubernetes fundamentals (control plane, nodes, pods, services, deployments).","Daily kubectl user familiar with contexts, namespaces, and auth.","Experience managing manifests with Helm/Kustomize or similar tooling.","Working knowledge of Git workflows (branches, PRs) and CI/CD automation.","Optional: exposure to CUE, GitOps controllers (Flux/Argo), or multi-cluster operations."]', '["kubernetes","timoni","cue","kluctl","fluxcd","gimlet","sveltos"]', 1759276800, '["rawkode"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GitOps is more than a controller—you need packaging discipline, environment orchestration, reconciliation pipelines, and developer UX. This path assembles opinionated tools so platform engineers can scale fleets while keeping guardrails intact."}]},{"type":"heading","attrs":{"level":2,"id":"learning-objectives"},"content":[{"type":"text","text":"Learning Objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Author type-safe application packages with CUE/Timoni and publish them as OCI artifacts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Orchestrate multi-environment rollouts with Kluctl’s structural diffs and templating."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bootstrap FluxCD 2, model sources/Kustomizations/HelmReleases, and control reconcilers with dependencies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Provide a developer-facing GitOps workflow via Gimlet while preserving Git-based audit trails."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manage add-ons across clusters using Sveltos’ intent-based policies and dynamic classifiers."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"videos-in-this-path"},"content":[{"type":"text","text":"Videos in This Path"}]},{"type":"heading","attrs":{"level":3,"id":"1-timoni-cue-powered-package-management"},"content":[{"type":"text","text":"1. "},{"type":"text","text":"Timoni: CUE-powered Package Management","marks":[{"type":"link","attrs":{"href":"/watch/timoni-cue-powered-package-management-for-kubernetes","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Configuration drift often starts with templating errors. Timoni couples CUE validation with OCI distribution so application definitions stay trustworthy."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Model services in CUE, enforce schemas, and catch mistakes before they hit the cluster."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Package modules/bundles and push them to OCI registries alongside container images."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Upgrade safely with server-side apply and observe minimal diffs."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timoni replaces ad-hoc Helm templating with type-safe unification, reducing runtime surprises."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OCI-backed bundles make promotion pipelines reproducible and auditable."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Convert an existing workload into a Timoni module + bundle, publish it to an OCI registry, and deploy it to staging."}]},{"type":"heading","attrs":{"level":3,"id":"2-hands-on-introduction-to-kluctl"},"content":[{"type":"text","text":"2. "},{"type":"text","text":"Hands-on Introduction to Kluctl","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-kluctl","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Once packages are solid, you need promotion discipline. Kluctl adds environment targets, previews, and pruning on top of GitOps."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Structure a Kluctl project with dev/stage/prod targets using Jinja2 and variable files."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Preview pending changes via "},{"type":"text","text":"kluctl diff","marks":[{"type":"code"}]},{"type":"text","text":" before committing to Git."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sequence resource deployments and clean out abandoned objects with "},{"type":"text","text":"kluctl prune","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kluctl glues templating, diffs, and GitOps together so environments stay predictable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Change previews provide guardrails missing from plain "},{"type":"text","text":"kubectl apply","marks":[{"type":"code"}]},{"type":"text","text":" or raw Git controllers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Build a three-target Kluctl repo, run diff/deploy for each environment, and document a rollback flow."}]},{"type":"heading","attrs":{"level":3,"id":"3-gitops-tutorial-with-fluxcd-2-gitops-toolkit"},"content":[{"type":"text","text":"3. "},{"type":"text","text":"GitOps Tutorial with FluxCD 2 (GitOps Toolkit)","marks":[{"type":"link","attrs":{"href":"/watch/gitops-tutorial-with-fluxcd-2-gitops-toolkit","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" FluxCD is the reconciliation engine for your GitOps platform. Master its controllers, dependencies, and health checks."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bootstrap FluxCD with "},{"type":"text","text":"gotk bootstrap","marks":[{"type":"code"}]},{"type":"text","text":" and connect it to a Git repo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define "},{"type":"text","text":"GitRepository","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"HelmRepository","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Kustomization","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"HelmRelease","marks":[{"type":"code"}]},{"type":"text","text":" resources."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chain dependencies, enforce health checks, and suspend/resume reconciliation during incidents."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FluxCD 2 decomposes GitOps into modular controllers—sources, kustomizations, Helm—so pipelines stay composable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dependency graphs and health gates ensure infrastructure comes up in the right order."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Bootstrap Flux into a test cluster, deploy an app with a HelmRelease, and add a dependency/health gate on a prerequisite component."}]},{"type":"heading","attrs":{"level":3,"id":"4-hands-on-introduction-to-gitops-with-gimlet"},"content":[{"type":"text","text":"4. "},{"type":"text","text":"Hands-on Introduction to GitOps with Gimlet","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-gitops-with-gimlet","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Developers need a polished workflow, not CRDs. Gimlet layers a UI and marketplace on top of Flux so teams ship without touching YAML."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Gimlet, connect it to a cluster, and trigger a buildpack-powered deploy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Watch how Gimlet writes Git commits/PRs that Flux reconciles."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manage configuration changes (replicas, env vars) and install add-ons from the marketplace."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gimlet offers a stair-step journey into GitOps—UI onboarding backed by Git commits you can review."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Focused developer workflows keep platform teams in control while devs stay productive."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Deploy an app via Gimlet, approve the resulting Git PR, and exercise a rollback using Git history."}]},{"type":"heading","attrs":{"level":3,"id":"5-hands-on-tutorial-of-project-sveltos"},"content":[{"type":"text","text":"5. "},{"type":"text","text":"Hands-on Tutorial of Project Sveltos","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-tutorial-of-project-sveltos","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" GitOps doesn’t stop at workloads. Sveltos pushes add-ons and policies across fleets based on intent and cluster metadata."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Target clusters with "},{"type":"text","text":"ClusterProfile","marks":[{"type":"code"}]},{"type":"text","text":" resources driven by labels, versions, or runtime state."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatically install add-ons as clusters register or change properties."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Integrate Sveltos with Flux so add-on definitions live in Git and reconcile continuously."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sveltos eliminates per-cluster babysitting—classifiers apply the right configs as fleets evolve."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GitOps integration keeps add-on state auditable and aligned with compliance requirements."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Label two clusters, create a ClusterProfile that deploys an ingress controller, and verify Sveltos heals manual drift."}]},{"type":"heading","attrs":{"level":2,"id":"bonus-practice"},"content":[{"type":"text","text":"Bonus Practice"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kluctl Controller Deep Dive","marks":[{"type":"link","attrs":{"href":"/watch/kluctl-new-features-and-updates","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — manage GitOps natively via CRDs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feature Flags via GitOps with Flipt","marks":[{"type":"link","attrs":{"href":"/watch/feature-flags-via-gitops-with-flipt","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — extend GitOps workflows beyond infrastructure."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"fleet-follow-ups"},"content":[{"type":"text","text":"Fleet Follow-ups"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wire Timoni and Kluctl bundles into Flux via OCI sources + Kustomizations for full GitOps automation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Onboard a pilot team to Gimlet, gather feedback, and codify approvals/rollbacks in Git workflows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine Flux alerts + Sveltos reconciliation metrics to build fleet-level operational dashboards and policies."}]}]}]}]}', 1790105224000);
INSERT INTO `learning_paths` (`id`, `title`, `description`, `difficulty`, `estimated_duration`, `prerequisites`, `technologies`, `published_at`, `authors`, `body`, `updated_at`) VALUES ('klustered-advanced-cluster-triage', 'Klustered: Advanced Cluster Triage', 'Master the craft of rescuing broken clusters. This path walks through real war‑room incidents so you can debug the control plane, container runtime, and host OS when kubectl alone is useless.', 'advanced', 447, '["Deep understanding of Kubernetes architecture (control plane, worker nodes, etcd, static pods).","Proficiency with kubectl, kubectl debug, and common triage commands (describe, logs, events).","Comfort administering Linux servers with systemd, journalctl, iptables, tc, and process tooling (ps, lsof).","Experience with container runtimes (containerd, CRI) and troubleshooting with crictl/ctr.","Familiarity with etcd administration (etcdctl, snapshots, compaction) and TLS fundamentals."]', '["kubernetes","containerd","etcd"]', 1759276800, '["rawkode"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Go beyond kubectl and develop a battle-tested methodology for diagnosing multi-layer outages. Each scenario highlights a different failure domain—nodes, networking, security, and host-level manipulation—so you can bring clusters back from the dead."}]},{"type":"heading","attrs":{"level":2,"id":"learning-objectives"},"content":[{"type":"text","text":"Learning Objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adopt a repeatable triage framework: validate symptoms, isolate the failing layer, and confirm the fix."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine Kubernetes logs with host forensics ("},{"type":"text","text":"journalctl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"systemctl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ps","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lsof","marks":[{"type":"code"}]},{"type":"text","text":") when the API server is lying—or gone."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repair control-plane failures by dissecting static pod manifests, TLS assets, and etcd health."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect malicious persistence (cron/systemd jobs, "},{"type":"text","text":"ld.so.preload","marks":[{"type":"code"}]},{"type":"text","text":", kubeconfig auth plugins) that reintroduce problems after a reboot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Harden clusters after recovery by applying network controls, auditing admission webhooks, and documenting runbooks."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"videos-in-this-path"},"content":[{"type":"text","text":"Videos in This Path"}]},{"type":"heading","attrs":{"level":3,"id":"1-marino-wijay--john-anderson"},"content":[{"type":"text","text":"1. "},{"type":"text","text":"Marino Wijay & John Anderson","marks":[{"type":"link","attrs":{"href":"/watch/marino-wijay-and-john-anderson","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Kubelet crashes and CNI misfires are the bread-and-butter incidents that escalate quickly. This episode establishes a systematic triage cadence."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Diagnose "},{"type":"text","text":"NodeNotReady","marks":[{"type":"code"}]},{"type":"text","text":" states by correlating kubelet logs, CNI status, and certificate errors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inspect static pod manifests and component arguments under "},{"type":"text","text":"/etc/kubernetes/manifests","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track down webhook failures and broken admission controllers that silently reject workloads."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trust but verify your cluster context and credentials before making changes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pod lifecycle issues often stem from lower layers—container runtime, CNI, or certificates—not the workload itself."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Reproduce a "},{"type":"text","text":"NodeNotReady","marks":[{"type":"code"}]},{"type":"text","text":" incident by breaking the CNI config in a test cluster, then repair it using the workflow demonstrated."}]},{"type":"heading","attrs":{"level":3,"id":"2-hans-kristian-flaatten--zach-wachtel"},"content":[{"type":"text","text":"2. "},{"type":"text","text":"Hans Kristian Flaatten & Zach Wachtel","marks":[{"type":"link","attrs":{"href":"/watch/hans-kristian-flaatten-and-zach-wachtel","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Slow control planes are harder than outright failures. This session shows how to hunt down etcd pain, I/O throttling, and sneaky persistence."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Profile control-plane latency and leader-election behaviour when etcd is under duress."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use low-level tools ("},{"type":"text","text":"crictl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"journalctl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"iostat","marks":[{"type":"code"}]},{"type":"text","text":") when "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" no longer returns data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Discover malicious cron/systemd jobs reintroducing broken configs after each reboot."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"etcd health directly governs API responsiveness; treat disk I/O and quotas as first-class SLOs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Persistent host tasks can undo your fixes—eradicate them or they’ll respawn the outage."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Simulate etcd I/O starvation (e.g., "},{"type":"text","text":"tc","marks":[{"type":"code"}]},{"type":"text","text":" or cgroup limits) and practice restoring health plus cleaning persistence hooks."}]},{"type":"heading","attrs":{"level":3,"id":"3-alex-jones--alistair-hey"},"content":[{"type":"text","text":"3. "},{"type":"text","text":"Alex Jones & Alistair Hey","marks":[{"type":"link","attrs":{"href":"/watch/alex-jones-and-alistair-hey","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Networking mysteries rarely announce themselves. This duel demonstrates how to peel back NodePorts, policies, and host firewalls."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trace traffic with "},{"type":"text","text":"kubectl exec","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"iptables -t nat","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"tc","marks":[{"type":"code"}]},{"type":"text","text":" to find where packets die."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Validate kube-controller-manager and kubelet configs when scheduling subtly fails."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guard yourself against sabotaged tooling (rogue aliases, modified kubeconfigs) that hinder troubleshooting."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-layer debugging beats guesswork—test from pod → node → service to pinpoint the break."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Always confirm your tools haven’t been tampered with; even "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" can be weaponized."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Inject latency with "},{"type":"text","text":"tc qdisc","marks":[{"type":"code"}]},{"type":"text","text":", observe service behaviour, then revert settings and record a runbook entry."}]},{"type":"heading","attrs":{"level":3,"id":"4-the-community-vs-rawkode"},"content":[{"type":"text","text":"4. "},{"type":"text","text":"The Community vs. Rawkode","marks":[{"type":"link","attrs":{"href":"/watch/the-community-vs-rawkode","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Security incidents often masquerade as outages. This group effort dissects a malicious kubeconfig helper and recovers the control plane."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit kubeconfig exec plugins to detect hostile authentication helpers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use classic Linux tooling ("},{"type":"text","text":"ps","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"at","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"env","marks":[{"type":"code"}]},{"type":"text","text":") to uncover suspicious activity on nodes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restore control-plane availability by editing static manifests and restarting kubelet safely."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"kubeconfig files are executable attack surfaces—treat them like code."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Static pod manifests provide single points of failure; secure and monitor them rigorously."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Craft a harmless kubeconfig exec helper, document how it executes, then disable it using RBAC and config policies."}]},{"type":"heading","attrs":{"level":3,"id":"5-klustered-11"},"content":[{"type":"text","text":"5. "},{"type":"text","text":"Klustered #11","marks":[{"type":"link","attrs":{"href":"/watch/klustered-11","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" The finale showcases deep Linux forensics—hidden processes, etcd DoS, and host firewalls—under extreme pressure."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect tampering techniques ("},{"type":"text","text":"ld.so.preload","marks":[{"type":"code"}]},{"type":"text","text":", rogue "},{"type":"text","text":"systemd","marks":[{"type":"code"}]},{"type":"text","text":" units) that hide processes and binaries."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recover from etcd quota exhaustion and network lockouts using snapshots, compaction, and targeted iptables rules."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine filesystem, network, and process evidence into a cohesive incident timeline."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Complex outages demand patience, logs, and note-taking before touching anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardened control planes require both Kubernetes and OS-level defenses (firewalls, file integrity, RBAC)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Build a lab where etcd hits its quota, practice compaction/defrag, then add iptables rules to lock down peer traffic."}]},{"type":"heading","attrs":{"level":2,"id":"bonus-practice-scenarios"},"content":[{"type":"text","text":"Bonus Practice Scenarios"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jetstack & CrashLoopBackoff","marks":[{"type":"link","attrs":{"href":"/watch/jetstack-and-crashbeerbackoff","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Chaos around admission webhooks and TLS."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"IBM & Nisum","marks":[{"type":"link","attrs":{"href":"/watch/ibm-and-nisum","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Multi-team debugging of broken upgrades."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Klustered Teams: Aerospike & Pixie Labs","marks":[{"type":"link","attrs":{"href":"/watch/klustered-teams-aerospike-and-pixielabs","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Service mesh vs. DNS whodunit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chainguard vs. Chainguard","marks":[{"type":"link","attrs":{"href":"/watch/klustered-teams-chainguard-vs-chainguard-2","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — Supply-chain sabotage meets cluster hardening."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"after-action-suggestions"},"content":[{"type":"text","text":"After-Action Suggestions"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn your notes into a written incident response playbook (symptom → hypothesis → command sequence)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automate recurring diagnostics with "},{"type":"text","text":"kubectl debug","marks":[{"type":"code"}]},{"type":"text","text":" profiles or Systemd/Ansible scripts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feed lessons learned into platform guardrails: enforce admission webhook health, lock down kubeconfig exec plugins, and monitor etcd quotas continuously."}]}]}]}]}', 1790105224000);
INSERT INTO `learning_paths` (`id`, `title`, `description`, `difficulty`, `estimated_duration`, `prerequisites`, `technologies`, `published_at`, `authors`, `body`, `updated_at`) VALUES ('mastering-kubernetes-security-posture-and-policy', 'Kubernetes Security Blueprint: Posture to Policy', 'Track, enforce, and extend Kubernetes security from baseline scans to policy-driven automation. This path combines posture management with Kyverno enforcement, policy observability, runtime threat detection, and jsPolicy-driven automation.', 'advanced', 406, '["Comfortable operating Kubernetes clusters (workloads, RBAC, admission controllers).","Ability to read/write YAML manifests and manage Helm/Kustomize workflows.","Experience with CI/CD pipelines and Git-based change management.","Familiarity with container security concepts (CVE remediation, least privilege).","Optional: basic Rego or policy-as-code exposure."]', '["kubescape","kyverno","cilium","hubble","opa","jspolicy","policy-reporter"]', 1759276800, '["rawkode"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Catch misconfigurations before they land, enforce intent with policy engines, wire everything into GitOps, and keep runtime observability tight. This path distills modern tooling so platform security teams can safeguard clusters without slowing developers."}]},{"type":"heading","attrs":{"level":2,"id":"learning-objectives"},"content":[{"type":"text","text":"Learning Objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Baseline cluster risk with Kubescape, covering live clusters and manifests."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enforce guardrails with Kyverno and observe violations via Policy Reporter dashboards."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Author alternative policies using OPA/Rego and JavaScript-based jsPolicy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect runtime threats with Cilium Tetragon and feed alerts into your monitoring stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Document remediation workflows that keep developers in the loop without slowing delivery."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"videos-in-this-path"},"content":[{"type":"text","text":"Videos in This Path"}]},{"type":"heading","attrs":{"level":3,"id":"1-hands-on-introduction-to-kubescape"},"content":[{"type":"text","text":"1. "},{"type":"text","text":"Hands-on Introduction to Kubescape","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-kubescape","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" You can’t fix what you can’t see. Kubescape provides the posture baseline across clusters and YAML before enforcing anything."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run Kubescape scans on live clusters and manifest directories."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Map findings to frameworks (NSA-CISA, CIS) and prioritize remediation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shift-left with the VS Code extension and early developer feedback."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Misconfigurations remain the primary Kubernetes risk—automate detection at every stage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubescape centralizes scoring and contextual guidance so teams know where to start."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Scan a staging cluster + repo, export SARIF, and assign the top failing control to an engineer with remediation notes."}]},{"type":"heading","attrs":{"level":3,"id":"2-kubescape-operator--saas"},"content":[{"type":"text","text":"2. "},{"type":"text","text":"Kubescape Operator & SaaS","marks":[{"type":"link","attrs":{"href":"/watch/kubescape-operator-and-saas","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Continuous scanning surfaces trends and RBAC exposure across fleets."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deploy the operator for ongoing CVE/config drift detection."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use Kubescape Cloud for multi-cluster dashboards and RBAC visualization."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filter vulnerabilities (e.g., RCE with fixes) and plan remediation waves."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Continuous posture management ensures improvements stick over time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"RBAC Visualizer untangles real-world permissions from sprawling YAML."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Install the operator, investigate the top RBAC risk via the visualizer, and document mitigating controls."}]},{"type":"heading","attrs":{"level":3,"id":"3-introduction-to-kyverno"},"content":[{"type":"text","text":"3. "},{"type":"text","text":"Introduction to Kyverno","marks":[{"type":"link","attrs":{"href":"/watch/introduction-to-kyverno","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Scans detect issues; policies prevent them. Kyverno’s Kubernetes-native approach keeps guardrails in YAML."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Kyverno and craft validate/mutate/generate policies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Roll policies out in audit mode before enforcing cluster-wide."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replace PodSecurityPolicy-era controls with Kyverno equivalents."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno uses familiar CRDs/YAML, lowering the barrier to policy-as-code."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit vs. enforce modes support safe adoption and phased rollouts."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Write a validate policy blocking privileged pods, deploy in audit mode, then enforce once violations drop to zero."}]},{"type":"heading","attrs":{"level":3,"id":"4-hands-on-with-policy-reporter"},"content":[{"type":"text","text":"4. "},{"type":"text","text":"Hands-on with Policy Reporter","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-with-policy-reporter","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Policies are useless if you can’t observe violations. Policy Reporter surfaces audit/enforce metrics and alerts."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deploy Policy Reporter and browse violation dashboards."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ship metrics to Prometheus/Grafana for compliance KPIs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trigger notifications when policies fail or drift returns."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Centralized telemetry turns policy-as-code into measurable outcomes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit mode + dashboards = smooth path to full enforcement."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Install Policy Reporter, create a Grafana panel showing Kyverno critical violations over time, and set a Slack alert."}]},{"type":"heading","attrs":{"level":3,"id":"5-introduction-to-open-policy-agent"},"content":[{"type":"text","text":"5. "},{"type":"text","text":"Introduction to Open Policy Agent","marks":[{"type":"link","attrs":{"href":"/watch/introduction-to-open-policy-agent","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Kyverno isn’t the only answer. OPA brings a general-purpose engine and Rego language for advanced scenarios."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explore the OPA architecture and how policy decision/delivery is decoupled."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Write basic Rego policies and evaluate them in the CLI/Playground."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Understand admission, API authorization, and other OPA integration patterns."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OPA’s flexibility makes it ideal for cross-cutting policy beyond Kubernetes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rego encourages reusable policy libraries that multiple teams can share."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Author a Rego policy that blocks hostPath volumes, test it in the Playground, and integrate it with "},{"type":"text","text":"kubectl opa test","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":3,"id":"6-cilium-tetragon-runtime-security-for-kubernetes"},"content":[{"type":"text","text":"6. "},{"type":"text","text":"Cilium Tetragon: Runtime Security for Kubernetes","marks":[{"type":"link","attrs":{"href":"/watch/restrict-access-to-secure-files-with-tetragon","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Admission controls can’t catch runtime abuse. Tetragon observes syscalls via eBPF and reacts in real time."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Tetragon and monitor file/process activity for sensitive paths."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create policies that kill or alert on suspicious behavior (e.g., shell spawning from a pod)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stream security events into Prometheus or SIEM pipelines."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Runtime visibility closes the gap between admission-time checks and live incidents."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"eBPF-powered policies have negligible overhead yet provide deep insight."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Configure a Tetragon policy blocking "},{"type":"text","text":"/etc/shadow","marks":[{"type":"code"}]},{"type":"text","text":" access, trigger a violation, and capture the alert to confirm response."}]},{"type":"heading","attrs":{"level":3,"id":"7-hands-on-introduction-to-jspolicy"},"content":[{"type":"text","text":"7. "},{"type":"text","text":"Hands-on Introduction to jsPolicy","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-jspolicy","target":null,"rel":null,"class":null,"title":null}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" Not every team wants Rego. jsPolicy lets JavaScript/TypeScript developers write policies using npm modules and runtime controller hooks."}]},{"type":"paragraph","content":[{"type":"text","text":"What you''ll learn:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Write validating/mutating policies in TypeScript using familiar language constructs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extend policies with npm dependencies for complex logic."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Leverage controller policies to react to events (e.g., auto-label pods) outside admission flow."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key takeaways:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"jsPolicy lowers the policy barrier for teams with JS expertise while keeping everything Kubernetes-native."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Controller policies unlock automation patterns beyond traditional admission controllers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hands-on drill:","marks":[{"type":"bold"}]},{"type":"text","text":" Create a jsPolicy that denies privileged pods and tags non-compliant resources for follow-up."}]},{"type":"heading","attrs":{"level":2,"id":"bonus-practice"},"content":[{"type":"text","text":"Bonus Practice"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno + Cosign Signatures","marks":[{"type":"link","attrs":{"href":"/watch/hands-on-introduction-to-sigstore","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — enforce image signatures before deployment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OPA Gatekeeper + Ratify","marks":[{"type":"link","attrs":{"href":"/watch/securing-cloud-native-workloads-hands-on-with-notary-project-oras-and-ratify","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — compare Gatekeeper admission checks with Kyverno."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"security-follow-ups"},"content":[{"type":"text","text":"Security Follow-ups"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat policies and posture baselines as code: store everything in Git, wire Flux/Argo, and require reviews."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pair runtime telemetry (Tetragon) with policy dashboards to feed incidents into your IR process."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build a remediation backlog: automate PRs or GitHub issues for high-risk violations surfaced by Kubescape/Policy Reporter."}]}]}]}]}', 1790105224000);
